WITH selected AS MATERIALIZED ( SELECT wiring.version, head.effective_release_id, member.package_version, wiring.graph_json, wiring.wiring_hash, convert_from(snapshot.canonical_bytes, 'UTF8')::jsonb AS manifest FROM catalog.wiring_activation AS active JOIN catalog.effective_release_heads AS head ON head.tenant_id = active.tenant_id AND head.environment = active.environment JOIN catalog.release_manifest_v3_snapshots AS snapshot ON snapshot.tenant_id = head.tenant_id AND snapshot.effective_release_id = head.effective_release_id AND convert_from(snapshot.canonical_bytes, 'UTF8')::jsonb #>> '{release,environment}' = $3 JOIN catalog.effective_release_packages AS member ON member.tenant_id = head.tenant_id AND member.effective_release_id = head.effective_release_id AND member.package_id = active.package_id JOIN catalog.wirings AS wiring ON wiring.tenant_id = active.tenant_id AND wiring.package_id = active.package_id AND wiring.package_version = member.package_version AND wiring.wiring_id = active.wiring_id AND wiring.version = $5 AND wiring.wiring_hash = active.confirmed_definition_hash WHERE active.tenant_id = $1 AND active.package_id = $2 AND active.environment = $3 AND active.wiring_id = $4 AND active.enabled AND NOT EXISTS ( SELECT 1 FROM catalog.wiring_tombstones AS dead WHERE dead.tenant_id = active.tenant_id AND dead.package_id = active.package_id AND dead.environment = active.environment AND dead.wiring_id = active.wiring_id ) ) SELECT selected.version, selected.effective_release_id, selected.package_version, selected.graph_json::text, selected.wiring_hash, COALESCE( jsonb_agg( jsonb_build_object( 'node-id', member.node_id, 'component', jsonb_build_object( 'scope', jsonb_build_object( 'tenant-id', $1::text, 'package-id', component.package_id, 'package-version', component.package_version ), 'component', component.component, 'interface-version', component.interface_version, 'operations', component.operations, 'component-digest', component.component_digest, 'imports', component.imports, 'imports-fingerprint', component.imports_fingerprint, 'effects', component.effects ) ) ORDER BY member.node_id COLLATE "C" ) FILTER (WHERE member.node_id IS NOT NULL), '[]'::jsonb )::text AS node_components, COALESCE( (SELECT jsonb_agg( jsonb_build_object( 'scope', jsonb_build_object( 'tenant-id', $1::text, 'package-id', component.package_id, 'package-version', component.package_version ), 'component', component.component, 'interface-version', component.interface_version, 'operations', component.operations, 'component-digest', component.component_digest, 'imports', component.imports, 'imports-fingerprint', component.imports_fingerprint, 'effects', component.effects ) ORDER BY projected.ordinality ) FROM jsonb_array_elements(selected.manifest -> 'components') WITH ORDINALITY AS projected(definition, ordinality) JOIN catalog.effective_release_packages AS release_package ON release_package.tenant_id = $1 AND release_package.effective_release_id = selected.effective_release_id AND release_package.package_id = projected.definition ->> 'package-id' JOIN catalog.component_library AS component ON component.tenant_id = release_package.tenant_id AND component.package_id = release_package.package_id AND component.package_version = release_package.package_version AND component.component = projected.definition ->> 'component' AND component.interface_version = projected.definition ->> 'interface-version' AND component.component_digest = projected.definition ->> 'digest'), '[]'::jsonb )::text AS components, jsonb_array_length(selected.manifest -> 'components') AS manifest_component_count FROM selected LEFT JOIN catalog.release_components AS member ON member.tenant_id = $1 AND member.effective_release_id = selected.effective_release_id AND member.wiring_package_id = $2 AND member.wiring_package_version = selected.package_version AND member.wiring_id = $4 AND member.wiring_version = $5 LEFT JOIN catalog.component_library AS component ON component.tenant_id = member.tenant_id AND component.package_id = member.package_id AND component.package_version = member.package_version AND component.component_digest = member.component_digest GROUP BY selected.version, selected.effective_release_id, selected.package_version, selected.graph_json, selected.wiring_hash, selected.manifest
